#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, player: PlayerId, costed: Costed, targets: &[Target]) -> CostDelta { let asker = &Asker::new(source, q.controller(source)); let Costed::Spell(spell) = costed else { return CostDelta::NONE; }; if true && ((q.chars(spell).colors.has(q.words(asker.source).color(Color::Green)) && q.chars(spell).is(CardType::Enchantment)) || (q.chars(spell).colors.has(q.words(asker.source).color(Color::White)) && q.chars(spell).is(CardType::Enchantment))) { CostDelta::more(2) } else { CostDelta::NONE } }

